from typing import List

def count_valid_hand_configurations(n: int, p: List[int], s: str) -> int:
    MOD = 998244353
    sp = [True for _ in range(n)]
    ans1 = 1
    for i in p:
        sp[i] = False
        if sp[(i + 1) % n]:
            if s[i] == "R":
                ans1 = 0
                break
        else:
            if s[i] == "?":
                ans1 *= 2
                ans1 %= MOD

    sp = [True for _ in range(n)]
    ans2 = 1
    for i in p:
        sp[(i + 1) % n] = False
        if sp[i]:
            if s[i] == "L":
                ans2 = 0
                break
        else:
            if s[i] == "?":
                ans2 *= 2
                ans2 %= MOD

    return (ans1 + ans2) % MOD
